const $=s=>document.querySelector(s),add=(tag,text,host)=>{const e=document.createElement(tag);e.textContent=text;host.append(e);return e;};let lang=initialLanguage(),exam=null,time=.5,playing=false,cut=true,last=0,error=false,replayStep=null,comparison=false,guided=null,guidedSaveError=false;const views=new Map();try{const data=JSON.parse(localStorage.getItem(repairExamKey)||'null');if(validRepairExam(data))exam=data;}catch{error=true;}
